def module_file(folder: Path) -> Path:
    """the scraper code: <name>.py, or the only other .py file (realestatecom-scraper has realestate.py)"""
    expected = folder / (folder.name.removesuffix("-scraper").replace("-", "_") + ".py")
    if expected.exists():
        return expected
    others = [p for p in folder.glob("*.py") if p.name not in ("run.py", "test.py")]
    return others[0]


def signature(node: ast.FunctionDef) -> str:
    """name(arg, arg=default, ...) without type hints"""
    args = node.args
    positional = args.posonlyargs + args.args
    defaults = [None] * (len(positional) - len(args.defaults)) + list(args.defaults)
    parts = [a.arg if d is None else f"{a.arg}={ast.unparse(d)}" for a, d in zip(positional, defaults)]
    parts += [a.arg if d is None else f"{a.arg}={ast.unparse(d)}" for a, d in zip(args.kwonlyargs, args.kw_defaults)]
    return f"{node.name}({', '.join(parts)})"


def parse_python(path: Path) -> ast.Module:
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", SyntaxWarning)  # old escape sequences in some scrapers' strings
        return ast.parse(path.read_text(encoding="utf-8"))


def scrape_functions(tree: ast.Module) -> list:
    """(signature, first docstring paragraph, return type) of every top-level scrape_* function (async, except in
    airfrance)"""
    functions = []
    for node in tree.body:
        if isinstance(node, (ast.AsyncFunctionDef, ast.FunctionDef)) and node.name.startswith("scrape"):
            doc = " ".join((ast.get_docstring(node) or "").split("\n\n")[0].split())
            if isinstance(node, ast.FunctionDef):
                doc = "(not async) " + doc
            functions.append((signature(node), doc.strip(), ast.unparse(node.returns) if node.returns else ""))
    return functions


def result_types(tree: ast.Module) -> list:
    """(name, [(field, can be null), ...]) of every TypedDict class of the module, in source order"""
    classes = {n.name: n for n in tree.body if isinstance(n, ast.ClassDef)}

    def is_typed_dict(node: ast.ClassDef) -> bool:
        bases = [ast.unparse(b) for b in node.bases]
        return any(
            b in ("TypedDict", "typing.TypedDict") or (b in classes and is_typed_dict(classes[b])) for b in bases
        )

    types = []
    for node in classes.values():
        if is_typed_dict(node):
            fields = []
            for item in node.body:
                if isinstance(item, ast.AnnAssign) and isinstance(item.target, ast.Name):
                    annotation = ast.unparse(item.annotation)
                    fields.append((item.target.id, annotation.startswith("Optional[") or "None" in annotation))
            types.append((node.name, fields))
    return types


def source_value(node: ast.expr) -> str:
    """a setting value as Python source, in double quotes when it is a literal"""
    try:
        return render_value(ast.literal_eval(node))
    except (ValueError, SyntaxError):
        return ast.unparse(node)


def base_config(tree: ast.Module) -> list:
    """(setting, value as source) of the module-level BASE_CONFIG dict"""
    for node in tree.body:
        if isinstance(node, ast.Assign) and any(
            isinstance(t, ast.Name) and t.id == "BASE_CONFIG" for t in node.targets
        ):
            if isinstance(node.value, ast.Dict):
                return [
                    (k.value, source_value(v))
                    for k, v in zip(node.value.keys, node.value.values)
                    if isinstance(k, ast.Constant)
                ]
    return []


def test_names(folder: Path) -> list:
    test_file = folder / "test.py"
    if not test_file.exists():
        return []
    return [
        n.name
        for n in parse_python(test_file).body
        if isinstance(n, (ast.AsyncFunctionDef, ast.FunctionDef)) and n.name.startswith("test_")
    ]


def render_value(value, indent: int = 0) -> str:
    """a literal as Python source in the repository's style (double quotes, black-like line breaks)"""
    pad = " " * indent
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if isinstance(value, (list, tuple)):
        items = [render_value(v, indent + 4) for v in list(value)[:2]]  # an example does not need every input item
        one_line = "[" + ", ".join(items) + "]"
        if len(one_line) + indent <= 80 or not items:
            return one_line
        return "[\n" + "".join(f"{pad}    {i},\n" for i in items) + pad + "]"
    if isinstance(value, dict):
        return "{" + ", ".join(f"{render_value(k)}: {render_value(v)}" for k, v in value.items()) + "}"
    return repr(value)


def sample_fields(folder: Path, files: list) -> list:
    """(file, keys) of the sample output files: the top-level keys of the first item (or of the object itself)"""
    fields = []
    for name in files:
        try:
            data = json.loads((folder / "results" / name).read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        item = data[0] if isinstance(data, list) and data else data
        if isinstance(item, dict) and item:
            fields.append((name, list(item)))
    return fields


def example_calls(folder: Path, functions: dict, stem: str) -> list:
    """(function, rendered call, is async) for the first call of each scrape_* function of the module found in run.py
    with literal arguments only (the scraper's own example inputs); functions maps a function name to is-async"""
    run_file = folder / "run.py"
    if not run_file.exists():
        return []
    tree = parse_python(run_file)
    modules = (stem, folder.name.removesuffix("-scraper").replace("-", "_"))
    aliases, names = set(), {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            aliases |= {a.asname or a.name for a in node.names if a.name in modules}
        elif isinstance(node, ast.ImportFrom) and node.module in modules:
            names |= {a.asname or a.name: a.name for a in node.names}
    # variables set to a literal (url = "https://..."), so a call can use them
    assigned = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
            try:
                assigned.append((node.lineno, node.targets[0].id, ast.literal_eval(node.value)))
            except (ValueError, SyntaxError):
                pass

    def literal(arg: ast.expr, line: int):
        if isinstance(arg, ast.Name):
            earlier = [
                value
                for lineno, name, value in sorted(assigned, key=lambda a: a[0])
                if name == arg.id and lineno < line
            ]
            if earlier:
                return earlier[-1]
        return ast.literal_eval(arg)

    calls = []
    for node in sorted((n for n in ast.walk(tree) if isinstance(n, ast.Call)), key=lambda n: (n.lineno, n.col_offset)):
        func = node.func
        if isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name) and func.value.id in aliases:
            name = func.attr
        elif isinstance(func, ast.Name) and func.id in names:
            name = names[func.id]
        else:
            continue
        target = f"{stem}.{name}"
        if name not in functions or name in [c[0] for c in calls] or any(k.arg is None for k in node.keywords):
            continue
        try:
            args = [render_value(literal(a, node.lineno), 8) for a in node.args]
            args += [f"{k.arg}={render_value(literal(k.value, node.lineno), 8)}" for k in node.keywords]
        except (ValueError, SyntaxError):
            continue  # an argument that is not a literal, for example a variable of run.py
        if any(len(a) > 200 for a in args):
            continue  # a long address would make the example hard to read
        one_line = f"{target}({', '.join(args)})"
        if len(one_line) + 12 <= 100 and "\n" not in one_line:
            call = one_line
        else:
            call = f"{target}(\n" + "".join(f"        {a},\n" for a in args) + "    )"
        calls.append((name, call, functions[name]))
    return calls


def readme_text(folder: Path) -> str:
    readme = folder / "README.md"
    return readme.read_text(encoding="utf-8") if readme.exists() else ""


def site_name(folder: Path) -> str:
    """the website name of the folder README title ("# Airbnb.com Scraper"), else the folder name"""
    lines = readme_text(folder).splitlines()
    name = re.sub(r"^#\s*|\s*scraper\s*$", "", lines[0] if lines else "", flags=re.I).strip()
    return name or folder.name.removesuffix("-scraper")


def readme_guide(folder: Path) -> str:
    """the first scrape guide article linked in the folder README (tag pages list many articles, not a guide)"""
    links = [link for link in GUIDE_LINK.findall(readme_text(folder)) if "/tag/" not in link]
    return links[0] if links else ""


def guide_title(url: str) -> str:
    """a title made from the article address: .../how-to-scrape-zoopla -> How to Scrape Zoopla"""
    words = url.rstrip("/").rsplit("/", 1)[-1].split("-")
    small = {"to", "and", "in", "of", "for", "a", "the", "with", "using"}
    return " ".join(w if w in small else w.capitalize() for w in words).replace("How To", "How to")


def dataset_label(file: str) -> str:
    """a label made from the file name: hotel_reviews.json -> Hotel reviews"""
    words = Path(file).stem.replace("_", " ").replace("-", " ")
    return words[:1].upper() + words[1:]


def scrapers() -> list:
    """everything the README table and llms.txt show about each scraper folder, sorted by website name"""
    extra = json.loads(EXTRA.read_text(encoding="utf-8")) if EXTRA.exists() else {}
    items = []
    for folder in sorted(p for p in ROOT.iterdir() if p.is_dir() and p.name.endswith("-scraper")):
        info = extra.get(folder.name, {})
        guides = info.get("guides") or ([{"url": readme_guide(folder)}] if readme_guide(folder) else [])
        labels = info.get("datasets", {})
        files = sorted(p.name for p in folder.glob("results/*.json"))
        # labelled files first, in the order of scrapers.json, then the others
        files = [f for f in labels if f in files] + [f for f in files if f not in labels]
        module = module_file(folder)
        tree = parse_python(module)
        is_async = {
            n.name: isinstance(n, ast.AsyncFunctionDef)
            for n in tree.body
            if isinstance(n, (ast.AsyncFunctionDef, ast.FunctionDef)) and n.name.startswith("scrape")
        }
        items.append(
            {
                "dir": folder.name,
                "name": info.get("name") or site_name(folder),
                "summary": info.get("summary", ""),
                "scrapes": info.get("scrapes", []),
                "notes": info.get("notes", []),
                "guides": [{"url": g["url"], "title": g.get("title") or guide_title(g["url"])} for g in guides],
                "datasets": [(f, labels.get(f) or dataset_label(f)) for f in files],
                "module": module.stem,
                "functions": scrape_functions(tree),
                "types": result_types(tree),
                "samples": sample_fields(folder, files),
                "config": base_config(tree),
                "tests": test_names(folder),
                "examples": example_calls(folder, is_async, module.stem),
            }
        )
    return sorted(items, key=lambda item: item["name"].lower())


def status_rank(results: list) -> int:
    """README order from the conclusions of a scraper's test jobs, like the badge of ci_status.py: every test passed,
    some passed, none passed, not run"""
    if not results:
        return 3
    passed = sum(1 for r in results if r == "success")
    return 0 if passed == len(results) else 1 if passed else 2


def readme_order(items: list, readme: str, status_file: Path = None) -> list:
    """the README rows: by the results of the last nightly run when its status.json is given (passing scrapers
    first, then partly passing, failing and not run), else in the order they already have; scrapers without a row
    come last, by website name"""
    if status_file:
        results = {}
        for job in json.loads(status_file.read_text(encoding="utf-8"))["tests"]:
            results.setdefault(job["dir"], []).append(job["conclusion"])
        return sorted(items, key=lambda s: (status_rank(results.get(s["dir"], [])), s["name"].lower()))
    start, end = table_span(readme)
    position = {d: i for i, d in enumerate(re.findall(r'<td><a href="\./([^/"]+)/">', readme[start:end]))}
    return sorted(items, key=lambda s: (position.get(s["dir"], len(position)), s["name"].lower()))


def readme_table(items: list, badge_repo: str, prefix: str = "./", headers: tuple = HEADERS) -> str:
    """the scraper table; prefix is the path from the README to the repository root ("./" or "../")"""
    rows = []
    for s in items:
        guide = " - ".join(f'<a href="{g["url"]}">{g["title"]}</a>' for g in s["guides"]) or "-"
        datasets = "\n".join(
            f'        <li><a href="{prefix}{s["dir"]}/results/{file}">{label}</a></li>' for file, label in s["datasets"]
        )
        badge = f"https://github.com/{badge_repo}/raw/ci-status/badges/{s['dir']}.svg"
        # the badge links to the scraper's page of the last run (each test with its job log), also on ci-status
        page = f"https://github.com/{badge_repo}/blob/ci-status/status/{s['dir']}.md"
        rows.append(
            "  <tr>\n"
            f'    <td><a href="{prefix}{s["dir"]}/">{s["name"]}</a></td>\n'
            f"    <td>{guide}</td>\n"
            f"    <td>\n    <ul>\n{datasets}\n    </ul>\n    </td>\n"
            f'    <td><a href="{page}"><img src="{badge}" alt="{s["dir"]}-status"></a></td>\n'
            "  </tr>\n"
        )
    header = "  <tr>\n" + "".join(f"    <td><strong>{h}</strong></td>\n" for h in headers) + "  </tr>\n"
    return f"{TABLE_NOTE}\n<table>\n\n{header}\n" + "\n".join(rows) + "\n</table>"


# what the settings of BASE_CONFIG mean, for the scraper READMEs
SETTINGS = {
    "unblocker": "Scrapfly's [Unblocker](https://scrapfly.io/docs/scrape-api/unblocker), its anti-bot bypass",
    "asp": "Anti Scraping Protection, the earlier name of the "
    "[Unblocker](https://scrapfly.io/docs/scrape-api/unblocker)",
    "country": "country of the proxy",
    "proxy_pool": "proxy pool (datacenter or residential)",
    "render_js": "render the page in a real browser",
    "rendering_wait": "wait after the page rendered, in milliseconds",
    "wait_for_selector": "wait for this element before returning the page",
    "auto_scroll": "scroll the page to load lazy content",
    "cache": "use Scrapfly's response cache",
    "debug": "keep a screenshot and the full log in the Scrapfly dashboard",
    "lang": "browser language",
    "os": "operating system of the browser",
    "session": "keep the same proxy and browser session between requests",
    "retry": "retry a failed request",
    "timeout": "request timeout in milliseconds",
}


def scraper_readme(s: dict, badge_repo: str) -> str:
    """the README.md of one scraper folder"""
    badge = f"https://github.com/{badge_repo}/raw/ci-status/badges/{s['dir']}.svg"
    page = f"https://github.com/{badge_repo}/blob/ci-status/status/{s['dir']}.md"
    module = s["module"]
    what = f"collects {s['summary']}" if s["summary"] else f"scrapes {s['name']}"
    out = [
        f"# {s['name']} Scraper\n\n{README_NOTE}\n",
        f"[![tests]({badge})]({page})\n",
        f"Example scraper that {what}, written in Python with the [Scrapfly](https://scrapfly.io/) web scraping API. "
        "Part of [scrapfly-scrapers](../README.md).\n",
    ]
    links = []
    if s["guides"]:
        links.append("- **Guide:** " + " · ".join(f"[{g['title']}]({g['url']})" for g in s["guides"]))
    links.append(
        f"- **Code:** [`{module}.py`]({module}.py) · **Example run:** [`run.py`](run.py) · "
        "**Tests:** [`test.py`](test.py)"
    )
    if s["datasets"]:
        links.append("- **Sample output:** " + " · ".join(f"[{label}](results/{f})" for f, label in s["datasets"]))
    out.append("\n".join(links) + "\n")
    if s["scrapes"]:
        out.append("## What it scrapes\n\n" + "\n".join(s["scrapes"]) + "\n")
    if s["functions"]:
        lines = []
        for sig, doc, returns in s["functions"]:
            sync = doc.startswith("(not async)")  # a regular function, run it without await
            doc = doc.removeprefix("(not async)").strip()
            lines.append(
                f"- `{sig}`"
                + (f" → `{returns}`" if returns else "")
                + (" (not async)" if sync else "")
                + (f": {doc}" if doc else "")
            )
        text = "## Functions\n\n" + "\n".join(lines) + "\n"
        if all(not doc.startswith("(not async)") for _, doc, _ in s["functions"]):
            text += "\nThe functions are `async`: run them with `asyncio.run(...)` or `await` them.\n"
        out.append(text)
    if s["examples"]:
        body = "".join(
            f"    {name.removeprefix('scrape_').strip('_') or 'result'} = {'await ' if is_async else ''}{call}\n"
            for name, call, is_async in s["examples"]
        )
        out.append(
            "### Example\n\nThe inputs are the examples of [`run.py`](run.py) (long lists cut short):\n\n"
            f"```python\nimport asyncio\nimport {module}\n\n\nasync def main():\n{body}\n\nasyncio.run(main())\n```\n"
        )
    if not s["types"] and s["samples"]:
        lines = []
        for name, keys in s["samples"]:
            shown = ", ".join(f"`{k}`" for k in keys[:40]) + (f", … ({len(keys) - 40} more)" if len(keys) > 40 else "")
            lines.append(f"- [`results/{name}`](results/{name}): {shown}")
        out.append(
            "## Output\n\nThe functions return plain dictionaries and lists. Fields of the sample output "
            "(top-level keys of the first item):\n\n" + "\n".join(lines) + "\n"
        )
    if s["types"]:
        lines = [
            f"- **`{name}`**: " + ", ".join(f"`{f}{'?' if optional else ''}`" for f, optional in fields)
            for name, fields in s["types"]
        ]
        optional = any(o for _, fields in s["types"] for _, o in fields)
        legend = "\nA field marked `?` can be `null`.\n" if optional else ""
        out.append(
            "## Output\n\nThe functions return plain dictionaries and lists. Fields:\n\n"
            + "\n".join(lines)
            + "\n"
            + legend
        )
    if s["config"]:
        lines = []
        for key, value in s["config"]:
            meaning = f": {SETTINGS[key]}" if key in SETTINGS else ""
            lines.append(f"- `{key}` = `{value}`{meaning}")
        out.append(
            f"## Scrapfly settings\n\n`BASE_CONFIG` in [`{module}.py`]({module}.py) holds the default settings of the "
            "requests, see the [Scrape API documentation](https://scrapfly.io/docs/scrape-api/getting-started):\n\n"
            + "\n".join(lines)
            + "\n"
        )
    if s["notes"]:
        out.append("## Notes\n\n" + "\n\n".join(s["notes"]) + "\n")
    tests = ", ".join(f"`{t}`" for t in s["tests"])
    out.append(
        "## Quick start\n\nRequires Python 3.10+ and [Poetry](https://python-poetry.org/docs/#installation).\n\n"
        "```shell\n"
        "git clone https://github.com/scrapfly/scrapfly-scrapers.git\n"
        f"cd scrapfly-scrapers/{s['dir']}\n"
        'export SCRAPFLY_KEY="YOUR SCRAPFLY KEY"   # from https://scrapfly.io/dashboard\n'
        "poetry install --no-root\n"
        "poetry run python run.py                  # example scrape, saves its output in ./results\n"
        "poetry run pytest test.py                 # the tests of this scraper\n"
        "```\n\n"
        + (f"Tests: {tests}; run one with `poetry run pytest test.py -k <test>`. " if tests else "")
        + "`run.py` and the tests scrape the live website, so they use Scrapfly credits.\n"
    )
    out.append("More: [all scrapers](../README.md) · [llms.txt](../llms.txt) for AI agents\n")
    return "\n".join(out)


def table_span(readme: str) -> tuple:
    """where the generated table (or the first table under "List of Scrapers") starts and ends in the README"""
    start = readme.find(TABLE_NOTE)
    if start < 0:
        start = readme.find("<table>", readme.find("## List of Scrapers"))
    end = readme.find("</table>", start) + len("</table>")
    if start < 0 or end < len("</table>"):
        sys.exit("docs.py: no scraper table found in README.md")
    return start, end


def replace_table(readme: str, table: str) -> str:
    """put the table in place of the current one"""
    start, end = table_span(readme)
    return readme[:start] + table + readme[end:]


def llms_txt(items: list) -> str:
    entries = []
    for s in items:
        details = [f"[code](https://github.com/{REPO}/tree/main/{s['dir']})"]
        if s["guides"]:
            details.append("guide: " + ", ".join(f"[{g['title']}]({g['url']})" for g in s["guides"]))
        samples = [
            f"[{label}](https://github.com/{REPO}/blob/main/{s['dir']}/results/{f})" for f, label in s["datasets"]
        ]
        if samples:
            details.append("sample output: " + ", ".join(samples))
        lines = [f"- **{s['name']}** (`{s['dir']}/`): " + " | ".join(details)]
        lines += [f"  - `{sig}`" + (f": {doc}" if doc else "") for sig, doc, _ in s["functions"]]
        entries.append("\n".join(lines))
    return LLMS_HEADER.format(count=len(items)) + "\n".join(entries) + "\n" + LLMS_FOOTER


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--check", action="store_true", help="exit 1 when a README table or llms.txt is out of date")
    parser.add_argument("--badge-repo", default=REPO, help="repository of the ci-status badges (for test copies)")
    parser.add_argument(
        "--status", type=Path, help="status.json of the ci-status branch: order the README rows by that nightly run"
    )
    args = parser.parse_args()
    items = scrapers()
    readme_path, llms_path = ROOT / "README.md", ROOT / "llms.txt"
    readme = readme_path.read_text(encoding="utf-8")
    rows = readme_order(items, readme, args.status)
    outputs = {readme_path: replace_table(readme, readme_table(rows, args.badge_repo)), llms_path: llms_txt(items)}
    for s in items:
        outputs[ROOT / s["dir"] / "README.md"] = scraper_readme(s, args.badge_repo)
    for language, headers in TRANSLATIONS.items():  # same rows in the same order as README.md
        path = ROOT / "docs" / f"README.{language}.md"
        if path.exists():
            text = path.read_text(encoding="utf-8")
            outputs[path] = replace_table(text, readme_table(rows, args.badge_repo, "../", headers))
    stale = [
        str(p.relative_to(ROOT))
        for p, text in outputs.items()
        if not p.exists() or p.read_text(encoding="utf-8") != text
    ]
    if args.check:
        if stale:
            shown = ", ".join(stale[:5]) + (f" and {len(stale) - 5} more" if len(stale) > 5 else "")
            sys.exit(f"out of date: {shown} - run python .github/scripts/docs.py")
        print("README tables and llms.txt are up to date")
        return
    for path, text in outputs.items():
        path.write_text(text, encoding="utf-8")
    print(f"{len(items)} scrapers; rewrote {', '.join(stale) or 'nothing (already up to date)'}")


if __name__ == "__main__":
    main()
